<?php
declare(strict_types=1);
/* WEBSAZA_PLATFORM_V3 */
function ws_dir():string{return defined('D')?(string)constant('D'):__DIR__.'/_data';}
function ws_now():string{return date('Y-m-d H:i:s');}
function ws_raw_read(string $f):array{$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];}
function ws_raw_write(string $f,array $x):bool{$l=@fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$q=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($q===false||@file_put_contents($t,$q,LOCK_EX)===false)return false;@chmod($t,0640);return @rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function ws_list(array $x):bool{$i=0;foreach($x as $k=>$_)if($k!==$i++)return false;return true;}
function ws_bucket(string $f):string{return basename($f,'.json');}
function ws_managed(string $f):bool{return in_array(ws_bucket($f),['branches','leads','assignments','events','referral_rewards','finance_payments','finance_remittances','finance_feedback','sms_queue','sms_log','manager_reports'],true);}
function ws_db():?PDO{static $db=null,$done=false;if($done)return $db;$done=true;if(!class_exists('PDO')||!in_array('sqlite',PDO::getAvailableDrivers(),true))return null;try{$db=new PDO('sqlite:'.ws_dir().'/websaza.sqlite3');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA journal_mode=WAL');$db->exec('PRAGMA synchronous=NORMAL');$db->exec('PRAGMA busy_timeout=5000');$db->exec('CREATE TABLE IF NOT EXISTS ds_meta(bucket TEXT PRIMARY KEY,kind TEXT,updated_at TEXT)');$db->exec('CREATE TABLE IF NOT EXISTS ds_rows(bucket TEXT,item_key TEXT,seq INTEGER,payload TEXT,PRIMARY KEY(bucket,item_key))');$db->exec('CREATE INDEX IF NOT EXISTS ds_seq ON ds_rows(bucket,seq)');$db->exec('CREATE TABLE IF NOT EXISTS contacts(phone TEXT PRIMARY KEY,first_seen_at TEXT,last_seen_at TEXT,last_status TEXT,last_lead_id TEXT,business TEXT,source TEXT,do_not_contact INTEGER DEFAULT 1,contact_count INTEGER DEFAULT 0,meta_json TEXT DEFAULT "{}")');$db->exec('CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,ref_id TEXT,phone TEXT,payload TEXT,created_at TEXT)');@chmod(ws_dir().'/websaza.sqlite3',0640);return $db;}catch(Throwable $e){$db=null;return null;}}
function ws_store_read(string $f):array{if(!ws_managed($f)||!($db=ws_db()))return ws_raw_read($f);$b=ws_bucket($f);try{$s=$db->prepare('SELECT kind FROM ds_meta WHERE bucket=?');$s->execute([$b]);$kind=$s->fetchColumn();if($kind===false){$legacy=ws_raw_read($f);ws_store_write($f,$legacy);return $legacy;}$s=$db->prepare('SELECT payload FROM ds_rows WHERE bucket=? ORDER BY seq');$s->execute([$b]);$rows=$s->fetchAll(PDO::FETCH_COLUMN);if($kind==='map'){if(!$rows)return [];$x=json_decode((string)$rows[0],true);return is_array($x)?$x:[];}$out=[];foreach($rows as $q){$x=json_decode((string)$q,true);if(is_array($x))$out[]=$x;}return $out;}catch(Throwable $e){return ws_raw_read($f);}}
function ws_store_write(string $f,array $x):bool{if(!ws_managed($f)||!($db=ws_db()))return ws_raw_write($f,$x);$b=ws_bucket($f);$kind=ws_list($x)?'list':'map';try{$db->beginTransaction();$db->prepare('DELETE FROM ds_rows WHERE bucket=?')->execute([$b]);$ins=$db->prepare('INSERT INTO ds_rows(bucket,item_key,seq,payload) VALUES(?,?,?,?)');if($kind==='map'){$ins->execute([$b,'__map__',0,json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}else{$seen=[];$i=0;foreach($x as $r){if(!is_array($r))continue;$k=(string)($r['id']??'');if($k===''||isset($seen[$k]))$k='row_'.$i.'_'.substr(hash('sha256',json_encode($r).$i),0,12);$seen[$k]=1;$ins->execute([$b,$k,$i++,json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}}$db->prepare('INSERT INTO ds_meta(bucket,kind,updated_at) VALUES(?,?,?) ON CONFLICT(bucket) DO UPDATE SET kind=excluded.kind,updated_at=excluded.updated_at')->execute([$b,$kind,ws_now()]);$db->commit();return true;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();return false;}}
function ws_backend():string{return ws_db()?'sqlite-wal':'json-fallback';}
function ws_phone(string $p):string{$d=preg_replace('/\D/','',$p)??'';if(str_starts_with($d,'0098'))$d=substr($d,4);elseif(str_starts_with($d,'98'))$d=substr($d,2);if(strlen($d)===10&&str_starts_with($d,'9'))$d='0'.$d;return strlen($d)===11&&str_starts_with($d,'09')?$d:'';}
function ws_contact_get(string $phone):?array{$p=ws_phone($phone);if($p==='')return null;if($db=ws_db()){try{$s=$db->prepare('SELECT * FROM contacts WHERE phone=?');$s->execute([$p]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}catch(Throwable $e){}}foreach(ws_raw_read(ws_dir().'/contact_registry.json') as $r)if(($r['phone']??'')===$p)return $r;return null;}
function ws_contact_seen(string $phone):bool{return ws_contact_get($phone)!==null;}
function ws_contact_touch(string $phone,array $m=[]):bool{$p=ws_phone($phone);if($p==='')return false;$n=ws_now();$st=(string)($m['status']??'');$lid=(string)($m['lead_id']??'');$biz=(string)($m['business']??'');$src=(string)($m['source']??'');$meta=json_encode($m,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}';if($db=ws_db()){try{$s=$db->prepare('INSERT INTO contacts(phone,first_seen_at,last_seen_at,last_status,last_lead_id,business,source,do_not_contact,contact_count,meta_json) VALUES(?,?,?,?,?,?,?,1,1,?) ON CONFLICT(phone) DO UPDATE SET last_seen_at=excluded.last_seen_at,last_status=CASE WHEN excluded.last_status<>"" THEN excluded.last_status ELSE contacts.last_status END,last_lead_id=CASE WHEN excluded.last_lead_id<>"" THEN excluded.last_lead_id ELSE contacts.last_lead_id END,business=CASE WHEN excluded.business<>"" THEN excluded.business ELSE contacts.business END,source=CASE WHEN excluded.source<>"" THEN excluded.source ELSE contacts.source END,do_not_contact=1,contact_count=contacts.contact_count+1,meta_json=excluded.meta_json');return $s->execute([$p,$n,$n,$st,$lid,$biz,$src,$meta]);}catch(Throwable $e){return false;}}$f=ws_dir().'/contact_registry.json';$rows=ws_raw_read($f);foreach($rows as $r)if(($r['phone']??'')===$p)return true;$rows[]=['phone'=>$p,'first_seen_at'=>$n,'last_seen_at'=>$n,'last_status'=>$st,'last_lead_id'=>$lid,'business'=>$biz,'source'=>$src,'do_not_contact'=>1,'contact_count'=>1,'meta'=>$m];return ws_raw_write($f,$rows);}
function ws_import_contacts(array $leads):int{$n=0;foreach($leads as $l){if(!is_array($l))continue;$p=ws_phone((string)($l['phone']??''));if($p!==''&&!ws_contact_seen($p)&&ws_contact_touch($p,['status'=>'historical','lead_id'=>(string)($l['id']??''),'business'=>(string)($l['business']??$l['name']??''),'source'=>(string)($l['source']??'legacy')]))$n++;}return $n;}
function ws_audit(string $kind,string $ref='',string $phone='',array $payload=[]):void{if(!($db=ws_db()))return;try{$s=$db->prepare('INSERT INTO audit(kind,ref_id,phone,payload,created_at) VALUES(?,?,?,?,?)');$s->execute([$kind,$ref,ws_phone($phone),json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}',ws_now()]);}catch(Throwable $e){}}
function ws_sms_pattern(string $settingsFile,string $mobile,string $pattern,array $attrs,string $kind='',string $ref=''):array{$c=ws_raw_read($settingsFile);if(array_key_exists('sms_enabled',$c)&&empty($c['sms_enabled']))return ['ok'=>false,'status'=>'disabled'];$key='';foreach(['sms_api_key','faraz_api_key','ippanel_api_key','api_key'] as $k)if(trim((string)($c[$k]??''))!==''){$key=trim((string)$c[$k]);break;}$to=ws_phone($mobile);$from=trim((string)($c['sms_sender']??$c['sms_from_number']??'90008361'));if($key===''||$to===''||trim($pattern)==='')return ['ok'=>false,'status'=>'not_configured'];$payload=['code'=>trim($pattern),'attributes'=>(object)$attrs,'recipient'=>$to,'line_number'=>$from?:'90008361','number_format'=>'english'];$ch=curl_init('https://api.iranpayamak.com/ws/v1/sms/pattern');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json','Api-Key: '.$key],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_IPRESOLVE=>CURL_IPRESOLVE_V4,CURLOPT_HTTP_VERSION=>CURL_HTTP_VERSION_1_1]);$out=(string)curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$j=json_decode($out,true);$ok=$http>=200&&$http<300&&(!is_array($j)||!isset($j['status'])||strtolower((string)$j['status'])==='success');ws_audit('sms_'.$kind,$ref,$to,['ok'=>$ok,'http'=>$http,'pattern'=>$pattern]);return ['ok'=>$ok,'status'=>$ok?'accepted':'rejected','http'=>$http];}
function ws_score(array $l):int{$s=(int)($l['lead_score']??0);if($s>0)return max(0,min(100,$s));$s=50;$site=mb_strtolower((string)($l['website_status']??''),'UTF-8');if($site===''||str_contains($site,'ندارد')||str_contains($site,'بدون'))$s+=22;elseif(str_contains($site,'ضعیف')||str_contains($site,'قدیمی'))$s+=14;if(!empty($l['source_url']))$s+=5;if(!empty($l['social_url'])||!empty($l['instagram']))$s+=6;if(!empty($l['proposal']))$s+=6;if(!empty($l['evidence']))$s+=6;return max(0,min(100,$s));}
function ws_location_bonus(array $l,array $b):int{$lc=trim((string)($l['city']??''));$bc=trim((string)($b['city']??''));return $lc!==''&&$bc!==''&&mb_strtolower($lc,'UTF-8')===mb_strtolower($bc,'UTF-8')?5:0;}
function ws_health():array{$db=ws_db();$contacts=0;$sets=[];if($db){try{$contacts=(int)$db->query('SELECT COUNT(*) FROM contacts')->fetchColumn();$sets=$db->query('SELECT bucket,kind,updated_at FROM ds_meta ORDER BY bucket')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}}else{$contacts=count(ws_raw_read(ws_dir().'/contact_registry.json'));}return ['ok'=>true,'version'=>'platform-v3','backend'=>ws_backend(),'contacts'=>$contacts,'datasets'=>$sets,'pdo_sqlite'=>class_exists('PDO')&&in_array('sqlite',PDO::getAvailableDrivers(),true),'time'=>ws_now()];}
